update vm_screen_data_config_count
set camera_num = #{cameraNum}, iot_num = #{iotNum}, radar_num = #{radarNum}, speaker_num = #{speakerNum}, uav_num = #{uavNum},
    recorder_num = #{recorderNum}, grid_num = #{gridNum}, grid_keeper_num = #{gridKeeperNum}, resources_num = #{resourcesNum}, alarm_type_num = #{alarmTypeNum},
    update_time = now(), is_customize = #{isCustomize}, screen_type = #{screenType}, update_by = #{updateBy}
    where id = #{id}

update.foreach:
update vm_screen_data_config_count
set camera_num = #{item.cameraNum}, iot_num = #{item.iotNum}, radar_num = #{item.radarNum}, speaker_num = #{item.speakerNum}, uav_num = #{item.uavNum},
recorder_num = #{item.recorderNum}, grid_num = #{item.gridNum}, grid_keeper_num = #{item.gridKeeperNum}, resources_num = #{item.resourcesNum},
alarm_type_num = (select count(1) from vm_screen_data_config where screen_data_config_id = #{item.id} and delete_flag = '0' and data_type = '9'),
update_time = now(), is_customize = #{item.isCustomize}
where id = #{item.id}

update vm_screen_data_config_count
set alarm_type_num = (select count(1) from vm_screen_data_config where screen_data_config_id = #{item.id} and delete_flag = '0' and data_type = '9'),
update_time = now()  where id = #{item.id}

mapper.insert:
update vm_screen_data_config set delete_flag = '1' where (screen_data_config_id, data_type, data_source, data_code) in (

    (#{item.screenDataConfigId}, #{item.dataType}, #{item.dataSource}, #{item.dataCode})

)

